'use strict';
const HousingUI=(()=>{
  const themes={wizard:{name:'달빛 별무리 마법사의 방',subtitle:'보랏빛 밤, 별이 쉬어 가는 작은 서재',wall:'#d5cbe8',side:'#b7a6cc',floor:'#e5dcf0',wood:'#9686ac',accent:'#f6dda2'},cafe:{name:'햇살 가득 카페 테라스',subtitle:'따스한 라테 한 잔과 느긋한 오후',wall:'#e4e8d0',side:'#c8d6b8',floor:'#e7d5b7',wood:'#ae9172',accent:'#e4b5ad'}};
  let home=economy.data.home;
  const button=document.createElement('button');button.className='glass tower-view-toggle';button.setAttribute('aria-pressed',String(home.aerial));document.querySelector('.game').append(button);
  const towerButton=document.createElement('button');towerButton.className='world-label tower-label';towerButton.textContent='✧ 포근섬 스카이 타워';towerButton.onclick=()=>setView(true);document.querySelector('.game').append(towerButton);
  function update(){home=economy.data.home;document.querySelector('.game').classList.toggle('aerial-view',home.aerial);button.textContent=home.aerial?'⌂ 앞마당으로 내려가기':'✧ 스카이 타워 · 항공 뷰';button.setAttribute('aria-pressed',String(home.aerial));$('#location').textContent=home.aerial?'스카이 타워 전망대':'우리 집 앞마당';$('.home-label').textContent='⌂ '+(home.theme==='wizard'?'달빛 마법사의 집':'햇살 카페 테라스');}
  function setView(value){keys.clear();state.target={...state.player};economy.setAerial(value);toast(value?'바람 위에서 포근섬을 내려다봐요.':'포근한 앞마당으로 돌아왔어요.')}
  button.onclick=()=>setView(!home.aerial);economy.subscribe(update);update();
  function polygon(c,points,color){c.fillStyle=color;c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fill()}
  function oval(c,x,y,rx,ry,color){c.fillStyle=color;c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fill()}
  function block(c,x,y,w,d,h,color){polygon(c,[[x,y],[x+w,y-w*.4],[x+w+d,y-w*.4+d*.45],[x+d,y+d*.45]],color);polygon(c,[[x,y],[x+d,y+d*.45],[x+d,y+d*.45+h],[x,y+h]],'#ad9c9866');polygon(c,[[x+d,y+d*.45],[x+w+d,y-w*.4+d*.45],[x+w+d,y-w*.4+d*.45+h],[x+d,y+d*.45+h]],'#88768c44')}
  function room(c,theme){const p=themes[theme];c.clearRect(0,0,600,330);c.fillStyle=theme==='wizard'?'#eae5f0':'#f2eee1';c.fillRect(0,0,600,330);oval(c,300,286,210,20,'#9f93991a');polygon(c,[[95,164],[296,70],[512,164],[310,272]],p.floor);polygon(c,[[95,164],[95,57],[296,0],[296,70]],p.side);polygon(c,[[296,70],[296,0],[512,64],[512,164]],p.wall);c.strokeStyle='#ffffff55';c.lineWidth=1;for(let i=0;i<8;i++){c.beginPath();c.moveTo(110+i*27,171+i*12);c.lineTo(305+i*26,81+i*12);c.stroke()}
    polygon(c,[[343,32],[429,57],[429,118],[343,83]],theme==='wizard'?'#7779aa':'#d3e5d3');c.strokeStyle='#fff4dd';c.lineWidth=5;c.strokeRect(353,53,1,29);if(theme==='wizard'){oval(c,390,68,13,14,'#f9e9af');oval(c,396,64,11,12,'#7779aa');block(c,127,127,52,24,63,p.wood);for(let i=0;i<6;i++)block(c,138+i*6,111-i*2,4,7,30,['#e5bbbf','#c5cbd9','#eddcaf'][i%3]);oval(c,306,209,92,40,'#c6b5d7');for(let i=0;i<12;i++)oval(c,306+Math.cos(i*2.4)*66,209+Math.sin(i*2.4)*24,2,2,'#f5e6b7');block(c,286,159,64,40,34,p.wood);oval(c,333,169,14,7,'#eedcb7');block(c,398,165,48,40,35,'#b7a2cd');block(c,391,141,58,29,24,'#d8c8e6');c.fillStyle='#fff0bb';c.font='23px serif';c.fillText('✧',246,67);c.fillText('✦',463,148)}else{for(let i=0;i<6;i++)block(c,103+i*25,158+i*12,4,5,35,'#d2bea1');block(c,319,87,106,22,51,p.wood);oval(c,362,118,6,4,'#fff3db');oval(c,406,106,6,4,'#fff3db');block(c,247,187,60,47,25,'#f4e7d0');oval(c,297,188,14,7,'#fdf8e9');oval(c,294,185,5,3,'#b28d68');block(c,208,206,25,20,26,p.accent);block(c,343,185,25,20,26,p.accent);for(const [x,y] of [[142,142],[447,168],[403,218]]){block(c,x,y,16,15,17,'#c69c85');oval(c,x+15,y-8,18,22,'#9fbc86');oval(c,x+6,y-16,12,18,'#bed29f')}}}
  function open(){let selected=home.theme;modal('나의 포근한 공간',`<p>빛과 취향으로 채우는 작은 쉼터</p><canvas id="roomPreview" width="600" height="330" aria-label="선택한 인테리어 테마 미리보기"></canvas><div class="theme-options">${Object.entries(themes).map(([id,t])=>`<button class="item" data-theme="${id}" aria-pressed="${selected===id}"><b>${t.name}</b><small>${t.subtitle}</small></button>`).join('')}</div><div class="housing-actions"><button class="primary" id="applyTheme">이 테마로 꾸미기</button><button class="item" id="visitTower">스카이 타워 전망대로 ↗</button></div><p id="housingStatus" class="fashion-status" role="status">현재 테마: ${themes[home.theme].name}</p>`);$('#modal').classList.add('wardrobe-modal');room($('#roomPreview').getContext('2d'),selected);document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{selected=b.dataset.theme;document.querySelectorAll('[data-theme]').forEach(a=>a.setAttribute('aria-pressed',String(a===b)));room($('#roomPreview').getContext('2d'),selected);$('#housingStatus').textContent='미리보기 · '+themes[selected].name});$('#applyTheme').onclick=()=>{economy.setTheme(selected);$('#housingStatus').textContent=themes[selected].name+' 테마를 적용했어요.'+(economy.storageOK?'':' 저장 불가: 이번 방문에만 유지됩니다.')};$('#visitTower').onclick=()=>{$('#modal').close();setView(true)}}
  function drawTower(c,x=918,y=438,scale=1){c.save();c.translate(x,y);c.scale(scale,scale);oval(c,0,8,40,14,'#76978d33');polygon(c,[[-20,5],[-12,-98],[0,-150],[10,-100],[20,5]],'#dae9e4');polygon(c,[[0,-150],[10,-100],[20,5],[0,12]],'#adcfcc');polygon(c,[[-24,-70],[0,-80],[25,-70],[0,-60]],'#eee6ef');polygon(c,[[-24,-70],[0,-60],[25,-70],[25,-56],[0,-44],[-24,-56]],'#bba9c5');c.strokeStyle='#fff9';c.lineWidth=2;for(let i=0;i<6;i++){c.beginPath();c.moveTo(-12,-90+i*15);c.lineTo(13,-90+i*15);c.stroke()}oval(c,0,-152,3,4,'#fff0bc');c.restore()}
  function drawAerial(c,t){c.fillStyle='#b9deda';c.fillRect(0,0,1600,900);for(let i=0;i<22;i++)oval(c,(i*193)%1600,130+i*34,18,2,'#e8f5ec55');oval(c,790,505,459,282,'#a8d1c5');oval(c,790,490,448,269,'#eee2bd');oval(c,790,480,420,243,'#c1d3a5');c.strokeStyle='#eae0c0';c.lineWidth=27;c.lineCap='round';c.beginPath();c.moveTo(590,408);c.quadraticCurveTo(895,320,1058,550);c.quadraticCurveTo(960,687,690,618);c.quadraticCurveTo(530,575,590,408);c.stroke();for(let i=0;i<28;i++){const a=i*2.4,x=790+Math.cos(a)*(310+i%3*13),y=480+Math.sin(a)*(150+i%4*9);oval(c,x,y,19,17,i%2?'#a5c28d':'#acc996');oval(c,x-4,y-5,11,9,'#bfd6a5')}
    for(const [x,y] of [[591,421],[708,350],[1015,526]]){block(c,x,y,48,39,23,'#e9dcc4');polygon(c,[[x-6,y],[x+21,y-37],[x+55,y-26],[x+88,y+1],[x+40,y+21]],'#aebda1')}
    for(let r=0;r<3;r++)for(let col=0;col<4;col++)oval(c,995+col*14+r*6,420+r*14,6,4,'#ae9671');oval(c,811,554,50,29,'#d4c9dc');drawTower(c,811,550,1.3);polygon(c,[[1012,667],[1044,654],[1115,717],[1084,732]],'#c4ad89');
    c.textAlign='center';c.fillStyle='#5d7e6b';c.font='14px sans-serif';c.fillText('나의 집',613,464);c.fillText('몽글 텃밭',1036,486);c.fillText('마을 광장',800,625);c.fillText('바닷가',1090,761);c.fillStyle='#658476';c.font='11px sans-serif';c.fillText('SKY TOWER OBSERVATORY',790,196);c.font='27px sans-serif';c.fillText('바람 위의 포근섬',790,237);c.font='12px sans-serif';c.fillText('천천히 내려다보면, 하루가 조금 더 다정해져요.',790,266);c.textAlign='start';
    for(let i=0;i<8;i++){const a=t/2000+i;c.globalAlpha=.3+.4*Math.sin(a)**2;oval(c,810+Math.cos(a)*60,400+Math.sin(a)*30,2,2,'#fff7d1')}c.globalAlpha=1;
  }
  $('.home-label').onclick=open;
  return {open,drawTower,drawAerial,get aerial(){return home.aerial}};
})();
